-- Consolidated legacy physical schema for migration tests.
CREATE SCHEMA base;
CREATE SCHEMA ops;
CREATE TABLE base.fitbit_activity_interval(subject_key VARCHAR, metric VARCHAR, record_id VARCHAR, start_at TIMESTAMP WITH TIME ZONE NOT NULL, end_at TIMESTAMP WITH TIME ZONE NOT NULL, "value" DOUBLE NOT NULL, offset_seconds INTEGER, end_offset_seconds INTEGER, source_date DATE, category VARCHAR, fetched_at TIMESTAMP WITH TIME ZONE NOT NULL, source_key VARCHAR NOT NULL, loaded_at TIMESTAMP WITH TIME ZONE NOT NULL, CHECK((metric IN ('steps', 'active-zone-minutes'))), PRIMARY KEY(subject_key, metric, record_id), CHECK((end_at > start_at)), CHECK((isfinite("value") AND ("value" >= 0))));;
CREATE TABLE base.fitbit_distance_interval(subject_key VARCHAR, record_id VARCHAR, start_at TIMESTAMP WITH TIME ZONE NOT NULL, end_at TIMESTAMP WITH TIME ZONE NOT NULL, offset_seconds INTEGER, end_offset_seconds INTEGER, source_date DATE NOT NULL, distance_meters DOUBLE NOT NULL, fetched_at TIMESTAMP WITH TIME ZONE NOT NULL, source_key VARCHAR NOT NULL, loaded_at TIMESTAMP WITH TIME ZONE NOT NULL, PRIMARY KEY(subject_key, record_id), CHECK((end_at > start_at)));;
CREATE TABLE base.fitbit_exercise(subject_key VARCHAR, record_id VARCHAR, start_at TIMESTAMP WITH TIME ZONE NOT NULL, end_at TIMESTAMP WITH TIME ZONE NOT NULL, offset_seconds INTEGER, end_offset_seconds INTEGER, source_date DATE NOT NULL, exercise_type VARCHAR NOT NULL, display_name VARCHAR NOT NULL, active_duration_seconds DOUBLE, fetched_at TIMESTAMP WITH TIME ZONE NOT NULL, source_key VARCHAR NOT NULL, loaded_at TIMESTAMP WITH TIME ZONE NOT NULL, PRIMARY KEY(subject_key, record_id), CHECK((end_at > start_at)));;
CREATE TABLE base.fitbit_heart_rate_minute(subject_key VARCHAR, data_source_family VARCHAR, start_at TIMESTAMP WITH TIME ZONE, aggregation_version VARCHAR, average DOUBLE NOT NULL, minimum DOUBLE NOT NULL, maximum DOUBLE NOT NULL, fetched_at TIMESTAMP WITH TIME ZONE NOT NULL, source_key VARCHAR NOT NULL, loaded_at TIMESTAMP WITH TIME ZONE NOT NULL, PRIMARY KEY(subject_key, data_source_family, start_at, aggregation_version), CHECK((date_trunc('minute', start_at) = start_at)), CHECK((isfinite(average) AND isfinite(minimum) AND isfinite(maximum))), CHECK(((minimum >= 0) AND (minimum <= average) AND (average <= maximum))));;
CREATE TABLE base.fitbit_heart_rate_zone_interval(subject_key VARCHAR, record_id VARCHAR, start_at TIMESTAMP WITH TIME ZONE NOT NULL, end_at TIMESTAMP WITH TIME ZONE NOT NULL, offset_seconds INTEGER, end_offset_seconds INTEGER, source_date DATE NOT NULL, "zone" VARCHAR NOT NULL, fetched_at TIMESTAMP WITH TIME ZONE NOT NULL, source_key VARCHAR NOT NULL, loaded_at TIMESTAMP WITH TIME ZONE NOT NULL, PRIMARY KEY(subject_key, record_id), CHECK((end_at > start_at)));;
CREATE TABLE base.fitbit_hrv_daily(subject_key VARCHAR, record_id VARCHAR, source_date DATE NOT NULL, rmssd_ms DOUBLE, deep_sleep_rmssd_ms DOUBLE, non_rem_heart_rate_bpm BIGINT, entropy DOUBLE, fetched_at TIMESTAMP WITH TIME ZONE NOT NULL, source_key VARCHAR NOT NULL, loaded_at TIMESTAMP WITH TIME ZONE NOT NULL, PRIMARY KEY(subject_key, record_id), UNIQUE(subject_key, source_date));;
CREATE TABLE base.fitbit_hrv_sample(subject_key VARCHAR, record_id VARCHAR, sample_at TIMESTAMP WITH TIME ZONE NOT NULL, offset_seconds INTEGER, source_date DATE NOT NULL, rmssd_ms DOUBLE, sdnn_ms DOUBLE, fetched_at TIMESTAMP WITH TIME ZONE NOT NULL, source_key VARCHAR NOT NULL, loaded_at TIMESTAMP WITH TIME ZONE NOT NULL, PRIMARY KEY(subject_key, record_id));;
CREATE TABLE base.fitbit_oxygen_saturation_daily(subject_key VARCHAR, record_id VARCHAR, source_date DATE NOT NULL, average_percent DOUBLE NOT NULL, lower_bound_percent DOUBLE NOT NULL, upper_bound_percent DOUBLE NOT NULL, standard_deviation_percent DOUBLE, fetched_at TIMESTAMP WITH TIME ZONE NOT NULL, source_key VARCHAR NOT NULL, loaded_at TIMESTAMP WITH TIME ZONE NOT NULL, PRIMARY KEY(subject_key, record_id), UNIQUE(subject_key, source_date));;
CREATE TABLE base.fitbit_respiratory_rate_daily(subject_key VARCHAR, record_id VARCHAR, source_date DATE NOT NULL, breaths_per_minute DOUBLE NOT NULL, fetched_at TIMESTAMP WITH TIME ZONE NOT NULL, source_key VARCHAR NOT NULL, loaded_at TIMESTAMP WITH TIME ZONE NOT NULL, PRIMARY KEY(subject_key, record_id), UNIQUE(subject_key, source_date));;
CREATE TABLE base.fitbit_respiratory_rate_sleep_summary(subject_key VARCHAR, record_id VARCHAR, sample_at TIMESTAMP WITH TIME ZONE NOT NULL, offset_seconds INTEGER, source_date DATE NOT NULL, full_breaths_per_minute DOUBLE, full_standard_deviation DOUBLE, full_signal_to_noise DOUBLE, deep_breaths_per_minute DOUBLE, deep_standard_deviation DOUBLE, deep_signal_to_noise DOUBLE, light_breaths_per_minute DOUBLE, light_standard_deviation DOUBLE, light_signal_to_noise DOUBLE, rem_breaths_per_minute DOUBLE, rem_standard_deviation DOUBLE, rem_signal_to_noise DOUBLE, fetched_at TIMESTAMP WITH TIME ZONE NOT NULL, source_key VARCHAR NOT NULL, loaded_at TIMESTAMP WITH TIME ZONE NOT NULL, PRIMARY KEY(subject_key, record_id));;
CREATE TABLE base.fitbit_resting_heart_rate_daily(subject_key VARCHAR, record_id VARCHAR, source_date DATE NOT NULL, beats_per_minute DOUBLE NOT NULL, fetched_at TIMESTAMP WITH TIME ZONE NOT NULL, source_key VARCHAR NOT NULL, loaded_at TIMESTAMP WITH TIME ZONE NOT NULL, PRIMARY KEY(subject_key, record_id), CHECK((isfinite(beats_per_minute) AND (beats_per_minute >= 0))));;
CREATE TABLE base.fitbit_sedentary_period(subject_key VARCHAR, record_id VARCHAR, start_at TIMESTAMP WITH TIME ZONE NOT NULL, end_at TIMESTAMP WITH TIME ZONE NOT NULL, offset_seconds INTEGER, end_offset_seconds INTEGER, source_date DATE NOT NULL, fetched_at TIMESTAMP WITH TIME ZONE NOT NULL, source_key VARCHAR NOT NULL, loaded_at TIMESTAMP WITH TIME ZONE NOT NULL, PRIMARY KEY(subject_key, record_id), CHECK((end_at > start_at)));;
CREATE TABLE base.fitbit_sleep_detail(subject_key VARCHAR, kind VARCHAR, record_id VARCHAR, sleep_id VARCHAR NOT NULL, source_date DATE NOT NULL, start_at TIMESTAMP WITH TIME ZONE NOT NULL, end_at TIMESTAMP WITH TIME ZONE NOT NULL, offset_seconds INTEGER, end_offset_seconds INTEGER, category VARCHAR, fetched_at TIMESTAMP WITH TIME ZONE NOT NULL, source_key VARCHAR NOT NULL, loaded_at TIMESTAMP WITH TIME ZONE NOT NULL, CHECK((kind IN ('sleep-stage', 'sleep-wake'))), PRIMARY KEY(subject_key, kind, record_id), CHECK((end_at > start_at)));;
CREATE TABLE base.fitbit_sleep_session(subject_key VARCHAR, record_id VARCHAR, source_date DATE NOT NULL, start_at TIMESTAMP WITH TIME ZONE NOT NULL, end_at TIMESTAMP WITH TIME ZONE NOT NULL, sleep_minutes DOUBLE, offset_seconds INTEGER, end_offset_seconds INTEGER, sleep_type VARCHAR, is_main_sleep BOOLEAN, fetched_at TIMESTAMP WITH TIME ZONE NOT NULL, source_key VARCHAR NOT NULL, loaded_at TIMESTAMP WITH TIME ZONE NOT NULL, minutes_awake BIGINT, minutes_in_sleep_period BIGINT, minutes_to_fall_asleep BIGINT, minutes_after_wake_up BIGINT, PRIMARY KEY(subject_key, record_id), CHECK((end_at > start_at)), CHECK(((sleep_minutes IS NULL) OR (isfinite(sleep_minutes) AND (sleep_minutes >= 0)))));;
CREATE TABLE base.fitbit_sleep_temperature_daily(subject_key VARCHAR, record_id VARCHAR, source_date DATE NOT NULL, nightly_temperature_celsius DOUBLE NOT NULL, baseline_temperature_celsius DOUBLE, relative_nightly_stddev_30d_celsius DOUBLE, fetched_at TIMESTAMP WITH TIME ZONE NOT NULL, source_key VARCHAR NOT NULL, loaded_at TIMESTAMP WITH TIME ZONE NOT NULL, PRIMARY KEY(subject_key, record_id), UNIQUE(subject_key, source_date));;
CREATE TABLE base.fitbit_vo2_max_daily(subject_key VARCHAR, record_id VARCHAR, source_date DATE NOT NULL, vo2_max_ml_kg_min DOUBLE NOT NULL, estimated BOOLEAN, cardio_fitness_level VARCHAR, covariance DOUBLE, fetched_at TIMESTAMP WITH TIME ZONE NOT NULL, source_key VARCHAR NOT NULL, loaded_at TIMESTAMP WITH TIME ZONE NOT NULL, PRIMARY KEY(subject_key, record_id), UNIQUE(subject_key, source_date));;
CREATE TABLE base.iphone_screen_time_event(event_key VARCHAR PRIMARY KEY, device_key VARCHAR NOT NULL, platform VARCHAR NOT NULL, source_stream VARCHAR NOT NULL, bundle_id VARCHAR NOT NULL, event_at TIMESTAMP WITH TIME ZONE NOT NULL, state VARCHAR NOT NULL, kind UINTEGER, object_key VARCHAR NOT NULL, segment_key VARCHAR NOT NULL, observed_at TIMESTAMP WITH TIME ZONE NOT NULL, parser_version VARCHAR NOT NULL, unknown_field_count UINTEGER NOT NULL, duplicate_occurrence_count UINTEGER NOT NULL, is_active BOOLEAN NOT NULL, loaded_at TIMESTAMP WITH TIME ZONE NOT NULL, CHECK((platform = 'ios')), CHECK((source_stream = 'app-in-focus')), CHECK((state IN ('start', 'end'))));;
CREATE TABLE base.mac_screen_time_event(event_key VARCHAR PRIMARY KEY, device_key VARCHAR NOT NULL, platform VARCHAR NOT NULL, source_stream VARCHAR NOT NULL, bundle_id VARCHAR NOT NULL, event_at TIMESTAMP WITH TIME ZONE NOT NULL, state VARCHAR NOT NULL, kind UINTEGER, object_key VARCHAR NOT NULL, segment_key VARCHAR NOT NULL, observed_at TIMESTAMP WITH TIME ZONE NOT NULL, parser_version VARCHAR NOT NULL, unknown_field_count UINTEGER NOT NULL, duplicate_occurrence_count UINTEGER NOT NULL, is_active BOOLEAN NOT NULL, loaded_at TIMESTAMP WITH TIME ZONE NOT NULL, CHECK((platform = 'macos')), CHECK((source_stream = 'app-usage')), CHECK((state IN ('start', 'end'))));;
CREATE TABLE base.owntracks_location(event_key VARCHAR PRIMARY KEY, device_key VARCHAR NOT NULL, event_at TIMESTAMP WITH TIME ZONE NOT NULL, latitude DOUBLE NOT NULL, longitude DOUBLE NOT NULL, accuracy_m DOUBLE, velocity_kmh DOUBLE, object_key VARCHAR NOT NULL, storage_generation BIGINT NOT NULL, received_at TIMESTAMP WITH TIME ZONE NOT NULL, loaded_at TIMESTAMP WITH TIME ZONE NOT NULL, parser_version VARCHAR NOT NULL, motionactivities VARCHAR[], CHECK((latitude BETWEEN -90 AND 90)), CHECK((longitude BETWEEN -180 AND 180)));;
CREATE TABLE ops.fitbit_coverage(subject_key VARCHAR, data_type VARCHAR, data_source_family VARCHAR, aggregation_version VARCHAR, range_start TIMESTAMP WITH TIME ZONE, range_end TIMESTAMP WITH TIME ZONE NOT NULL, fetched_at TIMESTAMP WITH TIME ZONE NOT NULL, source_key VARCHAR NOT NULL, content_sha256 VARCHAR NOT NULL, source_sha256 VARCHAR NOT NULL, PRIMARY KEY(subject_key, data_type, data_source_family, aggregation_version, range_start), CHECK((range_end > range_start)));;
CREATE TABLE ops.fitbit_deleted_record(subject_key VARCHAR, data_type VARCHAR, record_id VARCHAR, fetched_at TIMESTAMP WITH TIME ZONE NOT NULL, source_key VARCHAR NOT NULL, PRIMARY KEY(subject_key, data_type, record_id));;
CREATE TABLE ops.heartbeat(monitor_name VARCHAR PRIMARY KEY, succeeded_at TIMESTAMP WITH TIME ZONE NOT NULL, run_id VARCHAR NOT NULL, details JSON);;
CREATE TABLE ops.ingestion_metadata(object_key VARCHAR PRIMARY KEY, source_id VARCHAR NOT NULL, schema_version UINTEGER NOT NULL, subject_key VARCHAR NOT NULL, source_stream VARCHAR NOT NULL, logical_key VARCHAR NOT NULL, observed_at TIMESTAMP WITH TIME ZONE NOT NULL, content_sha256 VARCHAR NOT NULL, byte_size UBIGINT NOT NULL, status VARCHAR NOT NULL, parser_version VARCHAR, record_count UINTEGER, started_at TIMESTAMP WITH TIME ZONE NOT NULL, completed_at TIMESTAMP WITH TIME ZONE, error_type VARCHAR, error_message VARCHAR, retry_count UINTEGER DEFAULT(0) NOT NULL, storage_created_at TIMESTAMP WITH TIME ZONE, storage_generation UBIGINT, CHECK((status IN ('succeeded', 'failed'))));;
CREATE TABLE ops.iphone_screen_time_record(physical_id VARCHAR PRIMARY KEY, device_key VARCHAR NOT NULL, source_stream VARCHAR NOT NULL, segment_key VARCHAR NOT NULL, record_offset UBIGINT NOT NULL, record_metadata_offset UBIGINT NOT NULL, event_key VARCHAR NOT NULL, bundle_id VARCHAR NOT NULL, event_at TIMESTAMP WITH TIME ZONE NOT NULL, state VARCHAR NOT NULL, transition_reason VARCHAR, kind UINTEGER, app_version VARCHAR, app_build VARCHAR, platform_flag UINTEGER, parser_version VARCHAR NOT NULL, unknown_field_count UINTEGER NOT NULL, CHECK((source_stream = 'app-in-focus')));;
CREATE TABLE ops.iphone_screen_time_segment(device_key VARCHAR, source_stream VARCHAR, segment_key VARCHAR, observed_at TIMESTAMP WITH TIME ZONE NOT NULL, object_key VARCHAR NOT NULL, CHECK((source_stream = 'app-in-focus')), PRIMARY KEY(device_key, source_stream, segment_key));;
CREATE TABLE ops.job_lock(job_name VARCHAR PRIMARY KEY, owner_id VARCHAR NOT NULL, expires_at TIMESTAMP WITH TIME ZONE NOT NULL);;
CREATE TABLE ops.job_run(run_id VARCHAR PRIMARY KEY, job_name VARCHAR NOT NULL, status VARCHAR NOT NULL, started_at TIMESTAMP WITH TIME ZONE NOT NULL, completed_at TIMESTAMP WITH TIME ZONE, details JSON, CHECK((status IN ('running', 'succeeded', 'failed'))));;
CREATE TABLE ops.mac_screen_time_record(physical_id VARCHAR PRIMARY KEY, device_key VARCHAR NOT NULL, source_stream VARCHAR NOT NULL, segment_key VARCHAR NOT NULL, record_offset UBIGINT NOT NULL, record_metadata_offset UBIGINT NOT NULL, event_key VARCHAR NOT NULL, bundle_id VARCHAR NOT NULL, event_at TIMESTAMP WITH TIME ZONE NOT NULL, state VARCHAR NOT NULL, transition_reason VARCHAR, kind UINTEGER, app_version VARCHAR, app_build VARCHAR, platform_flag UINTEGER, parser_version VARCHAR NOT NULL, unknown_field_count UINTEGER NOT NULL, CHECK((source_stream = 'app-usage')));;
CREATE TABLE ops.mac_screen_time_segment(device_key VARCHAR, source_stream VARCHAR, segment_key VARCHAR, observed_at TIMESTAMP WITH TIME ZONE NOT NULL, object_key VARCHAR NOT NULL, CHECK((source_stream = 'app-usage')), PRIMARY KEY(device_key, source_stream, segment_key));;
CREATE TABLE ops.schema_migration (migration_id VARCHAR PRIMARY KEY, checksum VARCHAR NOT NULL, applied_at TIMESTAMPTZ NOT NULL);
